//! Actual B1BA70 initial activation, B1B8E0 jitter, B1BDF0 pose and B14310 caller.
use crate::{audio_bus_bank::Error,audio_plugin_factory::Memory,audio_frame_node_update::Runtime as Nodes,audio_timed_node_segment::Runtime as Paths,audio_timed_node_update::Runtime as Bindings,audio_timed_node_selection::{Runtime as Selection,Observer}};
use std::collections::BTreeMap;
fn word(r:&[u8],o:usize)->u32{u32::from_le_bytes(r[o..o+4].try_into().unwrap())}
fn set(r:&mut[u8],o:usize,v:u32){r[o..o+4].copy_from_slice(&v.to_le_bytes());}
fn owned(m:&BTreeMap<u32,Memory>,reference:u32,size:usize)->Result<&Memory,Error>{let v=m.get(&reference).ok_or(Error::UnresolvedReference)?;if reference==0||v.reference!=reference||v.raw.len()<size{return Err(Error::InvalidAllocation);}Ok(v)}
/// Immediate owner pose, including flag4 suppression. No timed interpolation.
pub fn pose(nodes:&Nodes,bindings:&mut Bindings,reference:u32)->Result<(),Error>{
 let n=owned(&nodes.nodes,reference,96)?;let count=word(&n.raw,36)as usize;if count==0{return Ok(());}let table=owned(&bindings.tables,word(&n.raw,32),count.checked_mul(4).ok_or(Error::InvalidAllocation)?)?;let refs:Vec<u32>=(0..count).map(|i|word(&table.raw,i*4)).collect();let xyz=n.raw[72..84].to_vec();
 for link in refs{let link=owned(&bindings.links,link,52)?;let target=word(&link.raw,48);if owned(&bindings.targets,target,60)?.raw[56]&4==0{bindings.targets.get_mut(&target).unwrap().raw[20..32].copy_from_slice(&xyz);}}Ok(())
}
fn jitter(paths:&mut Paths,amplitude:f32,observer:&mut impl Observer)->f32{let draw=paths.random.draw();observer.observe_random(draw);let normalized=draw as f32*f32::from_bits(0x38800200);let centered=normalized-1.;centered*amplitude}
pub fn activate(nodes:&mut Nodes,paths:&mut Paths,bindings:&mut Bindings,reference:u32,frame:u32,observer:&mut impl Observer)->Result<u32,Error>{
 let n=owned(&nodes.nodes,reference,96)?;let descriptor=word(&n.raw,12);if descriptor==0{return Ok(2);}nodes.nodes.get_mut(&reference).unwrap().raw[28]=1;
 let d=crate::audio_path_memory::read(&paths.descriptors,descriptor,16)?;let count=word(d,4)as i32;if count<=0{return Ok(37);}let points=word(d,0);let amp=[f32::from_bits(word(d,8)),f32::from_bits(word(d,12))];let p=crate::audio_path_memory::read(&paths.points,points,if count>1{32}else{16})?;let first:[u32;4]=std::array::from_fn(|i|word(p,i*4));let next:[u32;3]=if count>1{std::array::from_fn(|i|word(p,16+i*4))}else{[0;3]};
 if first[..3].iter().chain(next.iter()).any(|v|!f32::from_bits(*v).is_finite())||amp.iter().any(|v|!v.is_finite()){return Err(Error::Backend("nonfinite path activation requires native qualification"));}
 let mut base=std::array::from_fn::<_,3,_>(|i|f32::from_bits(first[i]));let n=nodes.nodes.get_mut(&reference).unwrap();n.raw[20..22].copy_from_slice(&1u16.to_le_bytes());for(i,bits)in first[..3].iter().enumerate(){set(&mut n.raw,72+i*4,*bits);}
 let numerator=first[3].wrapping_sub(1).wrapping_add(paths.interval)as i32;let quotient=numerator.checked_div(paths.interval as i32).ok_or(Error::Backend("native activation IDIV fault"))?;let duration=if quotient==0{1}else{quotient as u32};set(&mut n.raw,56,duration);
 let mut delta=[0f32;3];if count>1{let next=next.map(f32::from_bits);let identical=count<=2&&base.iter().zip(next.iter()).all(|(a,b)|a==b);base[0]+=jitter(paths,amp[0],observer);base[2]+=jitter(paths,amp[1],observer);let endpoint=if identical{base}else{[next[0]+jitter(paths,amp[0],observer),next[1],next[2]+jitter(paths,amp[1],observer)]};for i in 0..3{delta[i]=endpoint[i]-base[i];}}
 let n=nodes.nodes.get_mut(&reference).unwrap();for i in 0..3{set(&mut n.raw,72+i*4,base[i].to_bits());set(&mut n.raw,84+i*4,delta[i].to_bits());}pose(nodes,bindings,reference)?;
 let n=nodes.nodes.get_mut(&reference).unwrap();set(&mut n.raw,48,frame);set(&mut n.raw,52,frame.wrapping_add(duration));set(&mut n.raw,60,crate::audio_timed_node_segment::ratio(1,duration)?.to_bits());set(&mut n.raw,0,1);set(&mut n.raw,64,crate::audio_timed_node_segment::ratio(frame,duration)?.to_bits()|0x80000000);Ok(1)
}
struct Restart<'a,S>{selection:&'a mut Selection,observer:&'a mut S}
impl<S:Observer> crate::audio_timed_node_restart::Services for Restart<'_,S>{fn select_path(&mut self,nodes:&mut Nodes,paths:&mut Paths,reference:u32)->Result<bool,Error>{self.selection.select(nodes,paths,reference,self.observer)}}
/// Native outer caller: re-pose already initialized inactive nodes; keep the
/// activation result even when the subsequent restart returns17.
pub fn start(nodes:&mut Nodes,paths:&mut Paths,bindings:&mut Bindings,selection:&mut Selection,reference:u32,state:&mut[u8;8],frame:u32,observer:&mut impl Observer)->Result<u32,Error>{
 let n=owned(&nodes.nodes,reference,96)?;if word(&n.raw,0)!=0{return Ok(2);}if n.raw[28]!=0{pose(nodes,bindings,reference)?;return Ok(2);}let reused=word(state,4);
 if reused!=0{let index=u16::from_le_bytes(state[..2].try_into().unwrap());let n=nodes.nodes.get_mut(&reference).unwrap();set(&mut n.raw,8,reused);n.raw[16..18].copy_from_slice(&index.to_le_bytes());let base=word(&n.raw,4);set(&mut n.raw,12,base.wrapping_add(index as u32*16));}
 let result=activate(nodes,paths,bindings,reference,frame,observer)?;if nodes.nodes[&reference].raw[24]&2==0{let _=crate::audio_timed_node_restart::restart(nodes,paths,reference,&mut Restart{selection,observer})?;let n=&nodes.nodes[&reference];set(state,0,u16::from_le_bytes(n.raw[16..18].try_into().unwrap())as u32);set(state,4,word(&n.raw,8));}Ok(result)
}
#[cfg(test)]mod tests{
 use super::*;use serde_json::{Value,json};use crate::{audio_random::NativeRandom,audio_path_configuration::{Configuration,Services}};
 fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
 fn hex(b:&[u8])->String{b.iter().map(|v|format!("{v:02x}")).collect()}
 fn map(v:&Value)->BTreeMap<u32,Memory>{v.as_array().unwrap().iter().map(|e|{let reference=e["reference"].as_u64().unwrap()as u32;(reference,Memory{reference,raw:bytes(e["raw"].as_str().unwrap())})}).collect()}
 fn snap(map:&BTreeMap<u32,Memory>)->Vec<Value>{map.values().map(|m|json!({"reference":m.reference,"raw":hex(&m.raw)})).collect()}
 fn initial(b:&Value)->(Nodes,Paths,Bindings){(Nodes{reference:0,header:[0;12],table:Memory{reference:0,raw:vec![]},nodes:BTreeMap::from([(0x40006000,Memory{reference:0x40006000,raw:bytes(b["node"].as_str().unwrap())})])},Paths{descriptors:BTreeMap::from([(0x40007000,Memory{reference:0x40007000,raw:bytes(b["descriptor"].as_str().unwrap())})]),points:BTreeMap::from([(0x40007800,Memory{reference:0x40007800,raw:bytes(b["points"].as_str().unwrap())})]),random:NativeRandom::seeded(b["rng_state"].as_u64().unwrap()as u32),interval:1024},Bindings{tables:BTreeMap::from([(0x40008000,Memory{reference:0x40008000,raw:bytes(b["table"].as_str().unwrap())})]),links:map(&b["links"]),targets:map(&b["targets"])})}
 fn snapshot(nodes:&Nodes,paths:&Paths,bindings:&Bindings)->Value{json!({"node":hex(&nodes.nodes[&0x40006000].raw),"descriptor":hex(&paths.descriptors[&0x40007000].raw),"points":hex(&paths.points[&0x40007800].raw),"table":hex(&bindings.tables[&0x40008000].raw),"links":snap(&bindings.links),"targets":snap(&bindings.targets),"rng_state":paths.random.state()})}
 struct Backend{calls:Vec<Value>,allocation:Vec<u8>}
 impl Observer for Backend{fn observe_random(&mut self,value:u16){self.calls.push(json!({"kind":"rand","value":value}));}}
 impl Services for Backend{fn allocate_history(&mut self,pool:u32,bytes:u32)->Result<Option<Memory>,Error>{self.calls.push(json!({"kind":"allocate","pool":pool,"bytes":bytes,"reference":0x4000b100u32}));Ok(Some(Memory{reference:0x4000b100,raw:self.allocation.clone()}))}}
 #[test]fn audio_path_activation_matches726_native_initial_xyz_jitter_pose_signed_count_and_wrapping_cases(){let p:Value=serde_json::from_str(include_str!("../../../data/4.20/audio_path_activation_preparation.json")).unwrap();assert_eq!(p["passed"],true);assert_eq!(p["case_count"],726);for(i,row)in p["cases"].as_array().unwrap().iter().enumerate(){let(mut nodes,mut paths,mut bindings)=initial(&row["before"]);let mut backend=Backend{calls:vec![],allocation:vec![]};let result=activate(&mut nodes,&mut paths,&mut bindings,0x40006000,row["frame"].as_u64().unwrap()as u32,&mut backend).unwrap();assert_eq!(result,row["result"].as_u64().unwrap()as u32,"status {i}");assert_eq!(json!(backend.calls),row["calls"],"draws {i}");assert_eq!(snapshot(&nodes,&paths,&bindings),row["after"],"all initial state {i}");}}
 #[test]fn audio_path_activation_matches2880_native_configuration_outer_activation_restart_and_state_publication_compositions(){let p:Value=serde_json::from_str(&crate::audio_test_fixture("data/4.20/audio_path_configuration_activation_preparation.json")).unwrap();assert_eq!(p["passed"],true);assert_eq!(p["case_count"],2880);for(i,row)in p["cases"].as_array().unwrap().iter().enumerate(){let b=&row["before"];let(mut nodes,mut paths,mut bindings)=initial(b);let mut selection=Selection::default();let mut state:[u8;8]=bytes(b["state"].as_str().unwrap()).try_into().unwrap();let mut backend=Backend{calls:vec![],allocation:bytes(b["mask"].as_str().unwrap())};let result=crate::audio_path_configuration::configure(&mut nodes,&mut paths,&mut selection,0x40006000,&Configuration{descriptors:0x40007000,count:1,flags:row["flags"].as_u64().unwrap()as u32,loop_byte:1,state,pool:17},&mut backend).unwrap();assert_eq!(result,row["configured_result"].as_u64().unwrap()as u32,"config result {i}");assert_eq!(json!(backend.calls),row["configuration_calls"],"config calls {i}");let mut configured=snapshot(&nodes,&paths,&bindings);configured["state"]=json!(hex(&state));configured["mask"]=json!(hex(&selection.masks[&0x4000b100].raw));assert_eq!(configured,row["configured"],"config state {i}");backend.calls.clear();let result=start(&mut nodes,&mut paths,&mut bindings,&mut selection,0x40006000,&mut state,row["frame"].as_u64().unwrap()as u32,&mut backend).unwrap();assert_eq!(result,row["activated_result"].as_u64().unwrap()as u32,"activation status {i}");assert_eq!(json!(backend.calls),row["activation_calls"],"activation calls {i}");let mut after=snapshot(&nodes,&paths,&bindings);after["state"]=json!(hex(&state));after["mask"]=json!(hex(&selection.masks[&0x4000b100].raw));assert_eq!(after,row["after"],"all composed state {i}");}}
}
